source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full monochrome rows/columns mark the boundaries between repeated panels.
    candidates = {}
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            candidates[row[0]] = candidates.get(row[0], 0) + 1
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if len(set(col)) == 1:
            candidates[col[0]] = candidates.get(col[0], 0) + 1
    if not candidates:
        return [row[:] for row in grid]
    sep = max(candidates, key=candidates.get)
    row_cuts = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_cuts = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    def ranges(n, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < n:
            out.append((start, n))
        return out
    rs, cs = ranges(h, row_cuts), ranges(w, col_cuts)
    panels = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    if not panels:
        return [row[:] for row in grid]
    # The panel with the most non-background marks is the exemplar.
    freq = {}
    for row in grid:
        for v in row:
            if v != sep:
                freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get) if freq else sep
    def score(p):
        r0, r1, c0, c1 = p
        return sum(grid[r][c] != bg and grid[r][c] != sep
                   for r in range(r0, r1) for c in range(c0, c1))
    exemplar = max(panels, key=score)
    er0, er1, ec0, ec1 = exemplar
    pattern = [grid[r][ec0:ec1] for r in range(er0, er1)]
    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in panels:
        if (r1-r0, c1-c0) != (er1-er0, ec1-ec0):
            continue
        for dr in range(r1-r0):
            for dc in range(c1-c0):
                out[r0+dr][c0+dc] = pattern[dr][dc]
    return out
'''
